[asy]
unitsize(1cm);
pair P,Q,S,T,U,V,R;
P=(-3.9,0); Q=(3.9,0); S=(-1.95,1.95);
T=(1.95,1.95); U=(-3.9,3); V=(3.9,3);
R=(0,0);
draw(P--Q);
draw(U--V);
draw(R--S);
draw(R--T);
fill(R--T--V--U--S--cycle,gray(0.6));
draw(P--(-3.9,-3));
draw(Q--(3.9,-3));
label("3",(-3.9,-1.5),W);
label("3",(3.9,-1.5),E);
dot(P);
dot(Q);
dot(S);
dot(T);
dot(U);
dot(V);
dot(R);
fill((-3,2.8)..S--U..cycle,white);
fill((3,2.8)..T--V..cycle,white);
